import { Component, h, Host, Prop } from '@stencil/core';
import { __ } from '@wordpress/i18n';

import { FulfillmentStatus } from '../../../types';

const status = {
  unshipped: __('Not Shipped', 'surecart'),
  shipped: __('Shipped', 'surecart'),
  delivered: __('Delivered', 'surecart'),
  label_purchased: __('Label Purchased', 'surecart'),
  in_transit: __('In Transit', 'surecart'),
  returned: __('Returned', 'surecart'),
  failed: __('Failed', 'surecart'),
  voided: __('Label Voided', 'surecart'),
} as {
  [key in FulfillmentStatus]: string;
};

// Customer-facing overrides for statuses whose default (merchant) wording is too technical.
const customerStatus = {
  label_purchased: __('Preparing to Ship', 'surecart'),
  // A voided label just means shipping is being rearranged — items are still with the merchant.
  voided: __('Preparing to Ship', 'surecart'),
  // "Failed" alone is too ambiguous for a customer.
  failed: __('Delivery Failed', 'surecart'),
} as Partial<{
  [key in FulfillmentStatus]: string;
}>;

const type = {
  unshipped: 'default',
  shipped: 'info',
  delivered: 'success',
  label_purchased: 'info',
  in_transit: 'warning',
  returned: 'danger',
  failed: 'danger',
  voided: 'danger',
} as {
  [key in FulfillmentStatus]: 'default' | 'info' | 'success' | 'warning' | 'danger';
};

// Customer-facing type overrides — a voided label is not alarming to a customer.
const customerType = {
  voided: 'info',
} as Partial<{
  [key in FulfillmentStatus]: 'default' | 'info' | 'success' | 'warning' | 'danger';
}>;

@Component({
  tag: 'sc-fulfillment-shipping-status-badge',
  styleUrl: 'sc-fulfillment-shipping-status-badge.css',
  shadow: true,
})
export class ScFulfillmentShippingStatusBadge {
  /** The tag's statux type. */
  @Prop() status: FulfillmentStatus;

  /** Where the badge is shown. 'customer' applies friendlier wording for some statuses. */
  @Prop() context: 'admin' | 'customer' = 'admin';

  /** The tag's size. */
  @Prop({ reflect: true }) size: 'small' | 'medium' | 'large' = 'medium';

  /** Draws a pill-style tag with rounded edges. */
  @Prop({ reflect: true }) pill: boolean = false;

  /** Makes the tag clearable. */
  @Prop() clearable: boolean = false;

  /** Resolve the visible label, applying customer-friendly overrides in the customer context. */
  getLabel(): string {
    if (this.context === 'customer' && customerStatus[this.status]) {
      return customerStatus[this.status];
    }
    return status[this.status] || this.status;
  }

  /** Resolve the tag type, applying customer-friendly overrides in the customer context. */
  getType(): 'default' | 'info' | 'success' | 'warning' | 'danger' {
    if (this.context === 'customer' && customerType[this.status]) {
      return customerType[this.status];
    }
    return type?.[this?.status];
  }

  render() {
    // don't render if not shippable.
    if (this.status === 'unshippable') {
      return <Host style={{ display: 'none' }}></Host>;
    }

    return (
      <sc-tag type={this.getType()} pill={this.pill}>
        {this.getLabel()}
      </sc-tag>
    );
  }
}
